smart.css:
.smc-root {
  display: flex;
  flex-direction: column;
  gap: 28px;
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  font-size: 15px;
  line-height: 1.65;
}

.smc-root.smc-js [data-smc-reveal] {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 0.45s ease, transform 0.45s ease;
}

.smc-root.smc-js [data-smc-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

h2 {
  font-family: var(--smc-font-heading);
  font-size: 20px;
  line-height: 1.35;
  font-weight: 700;
  color: var(--smc-primary);
  margin-bottom: 14px;
}

h3 {
  font-family: var(--smc-font-heading);
  font-size: 17px;
  line-height: 1.35;
  font-weight: 600;
  color: var(--smc-primary);
  margin-bottom: 8px;
}

h4 {
  font-family: var(--smc-font-heading);
  font-size: 15px;
  font-weight: 600;
  color: var(--smc-primary);
  margin-bottom: 8px;
}

p {
  margin-bottom: 12px;
}
p:last-child {
  margin-bottom: 0;
}

.smc-badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--smc-accent);
  background: color-mix(in srgb, var(--smc-accent) 10%, transparent);
  padding: 4px 10px;
  border-radius: var(--smc-radius);
  margin-bottom: 12px;
}

.smc-tag {
  display: inline-block;
  font-size: 12px;
  font-weight: 600;
  color: var(--smc-muted);
  margin-bottom: 4px;
}

.smc-hero {
  background: var(--smc-surface);
  border-radius: var(--smc-radius);
  padding: 24px;
  border: 1px solid var(--smc-border);
}

.smc-hero__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  align-items: center;
}

@container smc (min-width: 680px) {
  .smc-hero__grid {
    grid-template-columns: 1.2fr 0.8fr;
  }
}

.smc-spec-brief {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px solid var(--smc-border);
}

.smc-spec-item {
  display: flex;
  flex-direction: column;
}

.smc-spec-num {
  font-family: var(--smc-font-heading);
  font-size: 20px;
  font-weight: 700;
  color: var(--smc-primary);
}

.smc-spec-lbl {
  font-size: 12px;
  color: var(--smc-muted);
}

.smc-figure {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.smc-figure img {
  max-width: 100%;
  height: auto;
  border-radius: var(--smc-radius);
  cursor: zoom-in;
}

.smc-figure figcaption {
  font-size: 12px;
  color: var(--smc-muted);
  margin-top: 8px;
}

.smc-gallery {
  background: var(--smc-surface);
  border-radius: var(--smc-radius);
  padding: 20px;
  border: 1px solid var(--smc-border);
}

.smc-gallery__header {
  margin-bottom: 16px;
}

.smc-gallery__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

@container smc (min-width: 600px) {
  .smc-gallery__grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
  }
}

.smc-gallery__item img {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  border-radius: var(--smc-radius);
  border: 1px solid var(--smc-border);
  cursor: zoom-in;
  transition: transform 0.2s ease;
}

.smc-gallery__item img:hover {
  transform: scale(1.02);
}

.smc-card {
  background: var(--smc-surface);
  border-radius: var(--smc-radius);
  padding: 24px;
  border: 1px solid var(--smc-border);
}

.smc-grid-2 {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}

@container smc (min-width: 680px) {
  .smc-grid-2 {
    grid-template-columns: 1fr 1fr;
  }
}

.smc-box--tip {
  background: color-mix(in srgb, var(--smc-primary) 5%, var(--smc-bg));
  border-left: 3px solid var(--smc-primary);
  padding: 16px;
  border-radius: 0 var(--smc-radius) var(--smc-radius) 0;
  margin-top: 14px;
}

.smc-grid-panels {
  align-items: stretch;
}

.smc-panel {
  background: var(--smc-surface);
  border-radius: var(--smc-radius);
  padding: 24px;
  border: 1px solid var(--smc-border);
  display: flex;
  flex-direction: column;
}

.smc-panel--highlight {
  background: color-mix(in srgb, var(--smc-accent) 4%, var(--smc-surface));
  border-color: color-mix(in srgb, var(--smc-accent) 25%, var(--smc-border));
}

.smc-panel__icon {
  color: var(--smc-accent);
  margin-bottom: 14px;
}

.smc-note-warn {
  background: color-mix(in srgb, var(--smc-accent) 8%, var(--smc-bg));
  padding: 12px 14px;
  border-radius: var(--smc-radius);
  border-left: 3px solid var(--smc-accent);
  font-size: 13.5px;
  margin-top: auto;
}

.smc-steps-flow {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
  margin-top: 14px;
}

@container smc (min-width: 600px) {
  .smc-steps-flow {
    grid-template-columns: 1fr 1fr;
  }
}

.smc-flow-item {
  display: flex;
  gap: 14px;
  background: var(--smc-bg);
  padding: 16px;
  border-radius: var(--smc-radius);
  border: 1px solid var(--smc-border);
}

.smc-flow-step {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--smc-primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 13px;
}

.smc-flow-item p {
  margin: 0;
  font-size: 14px;
}

.smc-summary-box {
  background: color-mix(in srgb, var(--smc-primary) 6%, var(--smc-surface));
  border: 1px solid color-mix(in srgb, var(--smc-primary) 20%, var(--smc-border));
  border-radius: var(--smc-radius);
  padding: 24px;
}

